  ,true,512,JSON_THROW_ON_ERROR);
  $existing=q_all('SELECT slug, content_json FROM life_dialogues');
  $versions=[];
  foreach($existing as $stored){$decoded=json_decode($stored['content_json'],true);$versions[$stored['slug']]=count($decoded['steps']??[]);}
  $insert=$pdo->prepare('INSERT INTO life_dialogues (slug,level_code,title,category,content_json) VALUES (?,?,?,?,?)');
  $upgrade=$pdo->prepare('UPDATE life_dialogues SET level_code=?,title=?,category=?,content_json=? WHERE slug=?');
  foreach($catalog as $scene){
    $fields=[$scene['level'],$scene['title'],$scene['category'],json_encode($scene,JSON_UNESCAPED_UNICODE)];
    if(!array_key_exists($scene['slug'],$versions))$insert->execute([$scene['slug'],...$fields]);
    elseif($versions[$scene['slug']]<count($scene['steps']))$upgrade->execute([...$fields,$scene['slug']]);
  }
  $scenes=q_all('SELECT content_json FROM life_dialogues ORDER BY level_code,slug');
  $data=array_map(static fn($v)=>json_decode($v['content_json'],true),$scenes);
} catch(Throwable $e){error_log('Life dialogues: '.$e->getMessage());$data=[];$catalogError=true;}
